func attachReturn(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*ifta.Return)(p)
	switch rel {
	case 0:
		r.AmendsReturn = (*ifta.Return)(child)
	case 1:
		r.FinalizedBy = (*tenant.User)(child)
	case 2:
		r.FiledBy = (*tenant.User)(child)
	case 3:
		r.ReopenedBy = (*tenant.User)(child)
	case 4:
		r.Lines = append(r.Lines, (*ifta.ReturnLine)(child))
	}
}

