func newTaxRate() unsafe.Pointer { return unsafe.Pointer(new(ifta.TaxRate)) }

func newNTaxRate(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]ifta.TaxRate, n)))
}

func ptrTaxRate(p unsafe.Pointer, c int32) any {
	r := (*ifta.TaxRate)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.JurisdictionID))
	case 2:
		return (*int64)(unsafe.Pointer(&r.Year))
	case 3:
		return (*int64)(unsafe.Pointer(&r.Quarter))
	case 4:
		return (*string)(unsafe.Pointer(&r.FuelType))
	case 5:
		return &r.RatePerGallon
	case 6:
		return &r.SurchargeRatePerGallon
	case 7:
		return &r.SourceNote
	case 8:
		return &r.SourceURL
	case 9:
		return &r.Rank
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueTaxRate(p unsafe.Pointer, c int32) any {
	r := (*ifta.TaxRate)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.JurisdictionID)
	case 2:
		return int64(r.Year)
	case 3:
		return int64(r.Quarter)
	case 4:
		return string(r.FuelType)
	case 5:
		return r.RatePerGallon
	case 6:
		return r.SurchargeRatePerGallon
	case 7:
		if r.SourceNote == "" {
			return nil
		}
		return r.SourceNote
	case 8:
		if r.SourceURL == "" {
			return nil
		}
		return r.SourceURL
	case 9:
		return r.Rank
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachTaxRate(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*ifta.TaxRate)(p)
	switch rel {
	case 0:
		r.Jurisdiction = (*ifta.Jurisdiction)(child)
	}
}

func init() {
	jurisdictionsTable.Relations[0].Target = usstatedb.UsStatesSchema()
	jurisdictionMileageEntriesTable.Relations[0].Target = tractordb.TractorsSchema()
	jurisdictionMileageEntriesTable.Relations[1].Target = JurisdictionsSchema()
	jurisdictionMileageEntriesTable.Relations[2].Target = tenantdb.UsersSchema()
	returnsTable.Relations[0].Target = ReturnsSchema()
	returnsTable.Relations[1].Target = tenantdb.UsersSchema()
	returnsTable.Relations[2].Target = tenantdb.UsersSchema()
	returnsTable.Relations[3].Target = tenantdb.UsersSchema()
	returnsTable.Relations[4].Target = ReturnLinesSchema()
	returnLinesTable.Relations[0].Target = ReturnsSchema()
	returnLinesTable.Relations[1].Target = JurisdictionsSchema()
	taxRatesTable.Relations[0].Target = JurisdictionsSchema()
}

